create table public.job_boards (id uuid primary key default gen_random_uuid(), source text not null check(source in ('greenhouse','lever','ashby','smartrecruiters')), board text not null check(board ~ '^[a-zA-Z0-9_-]{1,100}$'), company text not null check(length(company) between 1 and 200), enabled boolean not null default true, interval_minutes integer not null default 360 check(interval_minutes between 5 and 10080), next_run_at timestamptz not null default now(), created_at timestamptz not null default now(), unique(source,board));
create table public.ingestion_tasks (id uuid primary key default gen_random_uuid(), board_id uuid not null references public.job_boards(id) on delete cascade, status text not null default 'queued' check(status in ('queued','running','succeeded','failed')), attempts integer not null default 0 check(attempts between 0 and 3), available_at timestamptz not null default now(), lease_until timestamptz, lease_token uuid, imported_count integer, last_error text check(length(last_error)<=200), created_at timestamptz not null default now(), finished_at timestamptz);
create unique index ingestion_one_pending_per_board on public.ingestion_tasks(board_id) where status in ('queued','running');
create index ingestion_claim_idx on public.ingestion_tasks(status,available_at,lease_until);
alter table public.job_boards enable row level security;
alter table public.ingestion_tasks enable row level security;
grant select,insert,update on public.job_boards to service_role;
grant select on public.ingestion_tasks to service_role;
create function public.enqueue_due_boards() returns integer language plpgsql security definer set search_path='' as $$ declare b record; n integer:=0; begin update public.ingestion_tasks set status='failed',finished_at=now(),last_error='Worker lease expired after maximum attempts',lease_token=null,lease_until=null where status='running' and lease_until<now() and attempts>=3; for b in select id,interval_minutes from public.job_boards where enabled and next_run_at<=now() for update skip locked loop insert into public.ingestion_tasks(board_id) values(b.id) on conflict do nothing; if found then n:=n+1; end if; update public.job_boards set next_run_at=now()+make_interval(mins=>b.interval_minutes) where id=b.id; end loop; return n; end $$;
create function public.claim_ingestion_task() returns table(task_id uuid,token uuid,source text,board text,company text) language plpgsql security definer set search_path='' as $$ declare t public.ingestion_tasks%rowtype; new_token uuid:=gen_random_uuid(); begin select * into t from public.ingestion_tasks where attempts<3 and ((status='queued' and available_at<=now()) or (status='running' and lease_until<now())) order by created_at for update skip locked limit 1; if not found then return; end if; update public.ingestion_tasks set status='running',attempts=attempts+1,lease_until=now()+interval '15 minutes',lease_token=new_token where id=t.id; return query select t.id,new_token,b.source,b.board,b.company from public.job_boards b where b.id=t.board_id and b.enabled; if not found then update public.ingestion_tasks set status='failed',finished_at=now(),last_error='Board disabled',lease_token=null,lease_until=null where id=t.id; end if; end $$;
create function public.finish_ingestion_task(p_id uuid,p_token uuid,p_success boolean,p_count integer,p_error text) returns boolean language plpgsql security definer set search_path='' as $$ declare t public.ingestion_tasks%rowtype; begin select * into t from public.ingestion_tasks where id=p_id and status='running' and lease_token=p_token and lease_until>now() for update; if not found then return false; end if; if p_success then update public.ingestion_tasks set status='succeeded',finished_at=now(),imported_count=greatest(0,p_count),last_error=null,lease_token=null,lease_until=null where id=p_id; elsif t.attempts>=3 then update public.ingestion_tasks set status='failed',finished_at=now(),last_error=left(coalesce(p_error,'Ingestion failed'),200),lease_token=null,lease_until=null where id=p_id; else update public.ingestion_tasks set status='queued',available_at=now()+make_interval(mins=>t.attempts*5),last_error=left(coalesce(p_error,'Ingestion failed'),200),lease_token=null,lease_until=null where id=p_id; end if; return true; end $$;
revoke all on function public.enqueue_due_boards() from public; revoke all on function public.claim_ingestion_task() from public; revoke all on function public.finish_ingestion_task(uuid,uuid,boolean,integer,text) from public;
grant execute on function public.enqueue_due_boards() to service_role; grant execute on function public.claim_ingestion_task() to service_role; grant execute on function public.finish_ingestion_task(uuid,uuid,boolean,integer,text) to service_role;
